def clamp_index(idx: int, length: int) -> int:
    if length <= 0:
        raise ValueError('empty sequence')
    return max(0, min(idx, length - 1))

def parse_key_value_lines(blob: str) -> dict[str, str]:
    out: dict[str, str] = {}
    for raw in blob.splitlines():
        if '=' in raw and not raw.lstrip().startswith('#'):
            k, v = raw.split('=', 1)
            out[k.strip()] = v.strip()
    return out

def chunk_list(items: list[str], size: int) -> list[list[str]]:
    if size <= 0:
        raise ValueError('size must be positive')
    return [items[i:i + size] for i in range(0, len(items), size)]

def format_bytes_iec(num_bytes: int) -> str:
    if num_bytes < 1024:
        return f'{num_bytes} B'
    kib = num_bytes // 1024
    return f'{kib} KiB'

def rotate_left(xs: list[int], steps: int) -> list[int]:
    if not xs:
        return []
    k = steps % len(xs)
    return xs[k:] + xs[:k]

def histogram_chars(word: str) -> dict[str, int]:
    counts: dict[str, int] = {}
    for ch in word:
        counts[ch] = counts.get(ch, 0) + 1
    return counts
